#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <cstring>
#include <algorithm>
using namespace std;

using ll = long long;
using PII = pair<int, int>;

struct Edge {
    int to;
    ll cap;
    ll flow;
    int rev;
    Edge(int t, ll c, int r) : to(t), cap(c), flow(0), rev(r) {}
};

class FlowGraph {
public:
    int V, s, t;
    vector<vector<Edge>> adjList;
    vector<int> level;
    vector<int> nextEdge;

    FlowGraph(int nodes, int src, int dst) : V(nodes), s(src), t(dst) {
        adjList.resize(V);
        level.resize(V);
        nextEdge.resize(V);
    }

    void addEdge(int u, int v, ll capacity) {
        adjList[u].emplace_back(v, capacity, adjList[v].size());
        adjList[v].emplace_back(u, 0, adjList[u].size() - 1);
    }

    bool buildLevelGraph() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const auto& e : adjList[u]) {
                if (e.cap - e.flow > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll blockingFlow(int u, ll flow) {
        if (u == t) return flow;
        for (int& i = nextEdge[u]; i < (int)adjList[u].size(); ++i) {
            Edge& e = adjList[u][i];
            if (level[e.to] == level[u] + 1 && e.cap - e.flow > 0) {
                ll pushed = blockingFlow(e.to, min(flow, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    adjList[e.to][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll computeMaxFlow() {
        ll total = 0;
        while (buildLevelGraph()) {
            fill(nextEdge.begin(), nextEdge.end(), 0);
            while (ll pushed = blockingFlow(s, LLONG_MAX)) {
                total += pushed;
            }
        }
        return total;
    }
};

int fireDist[150][150];
int reachDist[150][150];
int cellId[150][150];
int gridSize, maxTime;
vector<string> gridData, capacityData;

vector<PII> getNeighbors(int r, int c) {
    vector<PII> res;
    if (r + 1 < gridSize) res.emplace_back(r+1, c);
    if (r - 1 >= 0) res.emplace_back(r-1, c);
    if (c + 1 < gridSize) res.emplace_back(r, c+1);
    if (c - 1 >= 0) res.emplace_back(r, c-1);
    return res;
}

void fireDistanceBFS(int startR, int startC) {
    memset(fireDist, -1, sizeof(fireDist));
    queue<PII> q;
    fireDist[startR][startC] = 0;
    q.push({startR, startC});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : getNeighbors(r, c)) {
            char cell = gridData[nr][nc];
            if ((cell != 'Z' && !isdigit(cell)) || fireDist[nr][nc] != -1) continue;
            fireDist[nr][nc] = fireDist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (isdigit(gridData[i][j]) && fireDist[i][j] == -1) {
                fireDist[i][j] = maxTime;
            }
        }
    }
}

void reachDistanceBFS(int startR, int startC) {
    memset(reachDist, -1, sizeof(reachDist));
    queue<PII> q;
    reachDist[startR][startC] = 0;
    q.push({startR, startC});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : getNeighbors(r, c)) {
            if (!isdigit(gridData[nr][nc]) || reachDist[nr][nc] != -1) continue;
            reachDist[nr][nc] = reachDist[r][c] + 1;
            q.push({nr, nc});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> gridSize >> maxTime;
    gridData.resize(gridSize);
    capacityData.resize(gridSize);
    for (int i = 0; i < gridSize; ++i) cin >> gridData[i];
    for (int i = 0; i < gridSize; ++i) cin >> capacityData[i];

    int fireR = -1, fireC = -1;
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            cellId[i][j] = i * gridSize + j + 1;
            if (gridData[i][j] == 'Z') {
                fireR = i;
                fireC = j;
            }
        }
    }

    fireDistanceBFS(fireR, fireC);

    int totalNodes = 2 * gridSize * gridSize + 2;
    FlowGraph flowNet(totalNodes, 0, totalNodes - 1);

    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (isdigit(gridData[i][j])) {
                int people = gridData[i][j] - '0';
                flowNet.addEdge(0, cellId[i][j], people);
                reachDistanceBFS(i, j);
                for (int r = 0; r < gridSize; ++r) {
                    for (int c = 0; c < gridSize; ++c) {
                        if (isdigit(capacityData[r][c]) && reachDist[r][c] != -1 &&
                            reachDist[r][c] <= fireDist[r][c] && reachDist[r][c] <= maxTime) {
                            bool allowed = true;
                            if (reachDist[r][c] == fireDist[r][c]) {
                                allowed = false;
                                for (auto [nr, nc] : getNeighbors(r, c)) {
                                    if (reachDist[nr][nc] != -1 &&
                                        reachDist[nr][nc] < fireDist[nr][nc]) {
                                        allowed = true;
                                        break;
                                    }
                                }
                            }
                            if (allowed) {
                                flowNet.addEdge(cellId[i][j], gridSize * gridSize + cellId[r][c], people);
                            }
                        }
                    }
                }
            }
        }
    }

    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (isdigit(capacityData[i][j])) {
                int cap = capacityData[i][j] - '0';
                flowNet.addEdge(gridSize * gridSize + cellId[i][j], totalNodes - 1, cap);
            }
        }
    }

    cout << flowNet.computeMaxFlow() << '\n';
}
